    openProblems: ["No prospective trials; international registries and inclusion in urothelial and HPV-squamous basket trials are the response.", "Late diagnosis mimicking benign stricture; urethroscopy for unexplained stricture or bleeding is the practical fix.", "Balancing organ preservation with cure in proximal tumours; chemoradiation series are growing."],
    targets: ["pd1", "nectin4", "fgfr3"], technologies: ["cytotoxic-chemotherapy", "imrt-igrt", "brachytherapy", "checkpoint-inhibitor", "adc"],
